package dev.arabicgames.phone;
import org.junit.*;import static org.junit.Assert.*;import fi.iki.elonen.NanoHTTPD;import java.util.*;import java.util.concurrent.atomic.AtomicReference;import org.json.*;
public class ApiProbeTest {
 @Test public void temporaryFailureDoesNotImposeQuotaCooldown(){assertEquals(1500,AiClient.retryDelay(AiClient.failure(503),0));assertEquals(15000,AiClient.retryDelay(AiClient.failure(429),0));assertEquals(3000,AiClient.retryDelay(AiClient.failure(503),1));assertEquals(60000,AiClient.retryDelay(AiClient.failure(429),4));}
 @Test public void preservesRetryAfterAndNeverIncludesResponseCredentials()throws Exception {NanoHTTPD server=new NanoHTTPD("127.0.0.1",0){public Response serve(IHTTPSession s){Response r=newFixedLengthResponse(Response.Status.SERVICE_UNAVAILABLE,"text/plain","sensitive provider payload");r.addHeader("Retry-After","120");return r;}};server.start();try{AiClient.send(new AiPreferences.Config("deepl","auto","RDR2","test-key",true),"Hello",List.of(),"http://127.0.0.1:"+server.getListeningPort());fail();}catch(AiClient.Failure e){assertEquals(503,e.status);assertEquals(120000,AiClient.retryDelay(e,4));assertTrue(e.getMessage().contains("503"));assertFalse(e.getMessage().contains("sensitive"));assertFalse(e.getMessage().contains("test-key"));}finally{server.stop();}}
 @Test public void probeTranslatesFixedTestPhraseAndMeasuresItsRequest()throws Exception {AtomicReference<String> body=new AtomicReference<>();NanoHTTPD server=new NanoHTTPD("127.0.0.1",0){public Response serve(IHTTPSession s){try{Map<String,String> files=new HashMap<>();s.parseBody(files);body.set(files.get("postData"));}catch(Exception e){throw new AssertionError(e);}return newFixedLengthResponse(Response.Status.OK,"application/json","{\"translations\":[{\"text\":\"تابع التقدم.\"}]}");}};server.start();try{AiClient.Probe result=AiClient.probe(new AiPreferences.Config("deepl","auto","RDR2","probe-secret",true),"http://127.0.0.1:"+server.getListeningPort());assertEquals("تابع التقدم.",result.arabic);assertTrue(result.ms>=0);assertEquals("Keep going.",new JSONObject(body.get()).getJSONArray("text").getString(0));assertFalse(body.get().contains("probe-secret"));}finally{server.stop();}}
 @Test public void shortDeepLContextIsExplicitAndDoesNotChangeSource()throws Exception {JSONObject body=AiRequest.body(new AiPreferences.Config("deepl","auto","RDR2","key",true,true),"Current line",List.of("old → قديم","latest → أخير"));assertTrue(body.getString("context").startsWith(AiRequest.INSTRUCTION));assertTrue(body.getString("context").endsWith("latest"));assertFalse(body.getString("context").contains("old →"));assertEquals("Current line",body.getJSONArray("text").getString(0));assertFalse(body.has("model_type"));}
}
